function readProtoVarint(buffer: Buffer, offset: number): [number, number] | null {
  let value = 0;
  let shift = 0;
  for (let cursor = offset; cursor < buffer.length; cursor += 1) {
    const byte = buffer[cursor];
    value += (byte & 0x7f) * (2 ** shift);
    if ((byte & 0x80) === 0) return [value, cursor + 1];
    shift += 7;
    if (shift > 49) return null;
  }
  return null;
}

function lengthDelimitedProtoFields(buffer: Buffer) {
  const fields: Buffer[] = [];
  let offset = 0;
  while (offset < buffer.length) {
    const tag = readProtoVarint(buffer, offset);
    if (!tag) return fields;
    offset = tag[1];
    const wireType = tag[0] & 7;
    if (wireType === 0) {
      const next = readProtoVarint(buffer, offset);
      if (!next) return fields;
      offset = next[1];
    } else if (wireType === 1) {
      offset += 8;
    } else if (wireType === 2) {
      const lengthValue = readProtoVarint(buffer, offset);
      if (!lengthValue) return fields;
      const length = lengthValue[0];
      offset = lengthValue[1];
      if (length < 0 || offset + length > buffer.length) return fields;
      const value = buffer.subarray(offset, offset + length);
      if (value.length > 0) fields.push(value);
      offset += length;
    } else if (wireType === 5) {
      offset += 4;
    } else {
      return fields;
    }
  }
  return fields;
}

function printableStrings(buffer: Buffer) {
  const strings: string[] = [];
  let start = -1;
  for (let index = 0; index <= buffer.length; index += 1) {
    const byte = index < buffer.length ? buffer[index] : 0;
    const printable = byte >= 32 && byte <= 126;
    if (printable && start < 0) start = index;
    if ((!printable || index === buffer.length) && start >= 0) {
      if (index - start >= 4) strings.push(buffer.toString("utf8", start, index));
      start = -1;
    }
  }
  return strings;
}

function base64Decode(value: string): Buffer | null {
  const compact = value.trim().replace(/\s+/g, "");
  if (!compact || compact.length < 4 || !/^[A-Za-z0-9+/]+={0,2}$/.test(compact)) return null;
  try {
    const padded = compact.padEnd(Math.ceil(compact.length / 4) * 4, "=");
    const decoded = Buffer.from(padded, "base64");
    return decoded.length ? decoded : null;
  } catch {
    return null;
  }
}

function antigravityDecodedStateBuffers(rawBase64: string) {
  const first = base64Decode(rawBase64);
  if (!first) return [];
  const buffers: Buffer[] = [];
  const queue = [first];
  const seen = new Set<string>();
  while (queue.length && buffers.length < 300) {
    const buffer = queue.shift();
    if (!buffer || buffer.length > 1_000_000) continue;
    const key = `${buffer.length}:${buffer.subarray(0, 16).toString("hex")}`;
    if (seen.has(key)) continue;
    seen.add(key);
    buffers.push(buffer);
    for (const field of lengthDelimitedProtoFields(buffer)) {
      queue.push(field);
      for (const text of printableStrings(field)) {
        if (text.length >= 16) {
          const decoded = base64Decode(text);
          if (decoded) queue.push(decoded);
        }
      }
    }
    for (const text of printableStrings(buffer)) {
      if (text.length >= 16) {
        const decoded = base64Decode(text);
        if (decoded) queue.push(decoded);
      }
    }
  }
  return buffers;
}

function isAntigravityModelName(value: string) {
  return /^(Gemini|Claude|GPT-OSS)\b/i.test(value)
    && value.length <= 80
    && !value.includes("/")
    && !value.includes("@")
    && (/\d/.test(value) || /^Claude\b/i.test(value));
}

function antigravityModelsFromState(rawBase64: string): ProviderModelOption[] {
  const descriptors = new Set(["Fast", "Limited time", "Recommended"]);
  const strings = antigravityDecodedStateBuffers(rawBase64)
    .flatMap(printableStrings)
    .map((value) => value.replace(/\s+/g, " ").trim())
    .filter(Boolean);
  const models: ProviderModelOption[] = [];
  const seen = new Set<string>();
  for (let index = 0; index < strings.length; index += 1) {
    const displayName = strings[index];
    if (!isAntigravityModelName(displayName)) continue;
    const normalized = displayName.toLowerCase();
    if (seen.has(normalized)) continue;
    seen.add(normalized);
    const notes: string[] = [];
    for (const next of strings.slice(index + 1, index + 5)) {
      if (isAntigravityModelName(next)) break;
      if (descriptors.has(next) && !notes.includes(next)) notes.push(next);
    }
    models.push({
      ...providerModelOption(
        antigravityModelID(displayName),
        displayName,
        notes.length ? notes.join(" · ") : "Antigravity reasoning model from local Antigravity account state."
      ),
      isDefault: models.length === 0
    });
  }
  if (!models.length) return [];
  return [
    ...models,
    {
      ...providerModelOption(
        "antigravity-default",
        models[0].displayName,
        "Legacy Open Assist default. Antigravity will use its selected reasoning model."
      ),
      hidden: true
    }
  ];
}

let antigravityModelCache: { expiresAt: number; value: ProviderModelOption[] } | null = null;

function antigravityGlobalStorageDatabase() {
  return path.join(os.homedir(), "Library", "Application Support", "Antigravity", "User", "globalStorage", "state.vscdb");
}

async function readAntigravityUnifiedStateValue(key: string) {
  const database = antigravityGlobalStorageDatabase();
  if (!fs.existsSync(database)) return "";
  const { stdout } = await execFileAsync("sqlite3", [
    "-noheader",
    "-batch",
    database,
    `select value from ItemTable where key='${key.replace(/'/g, "''")}' limit 1;`
  ], { timeout: 2500 });
  return stdout.trim();
}

async function loadAntigravityModelsFromState(): Promise<ProviderModelOption[]> {
  const now = Date.now();
  if (antigravityModelCache && antigravityModelCache.expiresAt > now) return antigravityModelCache.value;
  const rawState = await readAntigravityUnifiedStateValue("antigravityUnifiedStateSync.userStatus");
  const models = uniqueProviderModels(antigravityModelsFromState(String(rawState)));
  const value = models.length ? models : fallbackModelOptionsForBackend("antigravityCLI");
  antigravityModelCache = { expiresAt: now + 60_000, value };
  return value;
}

function antigravityPlanFromState(rawBase64: string) {
  const strings = antigravityDecodedStateBuffers(rawBase64)
    .flatMap(printableStrings)
    .map((value) => value.replace(/\s+/g, " ").trim());
  return strings.find((value) => /^Google AI (Pro|Ultra)$/i.test(value))
    ?? strings.find((value) => /^Google AI\b/i.test(value))
    ?? null;
}

async function refreshAntigravityUsageFromState() {
  const rawState = await readAntigravityUnifiedStateValue("antigravityUnifiedStateSync.userStatus");
  const planType = antigravityPlanFromState(String(rawState));
  if (!planType) return;
  const existing = runtimeUsageByBackend.antigravityCLI;
  runtimeUsageByBackend.antigravityCLI = makeProviderUsage(
    "antigravityCLI",
    existing?.primary ?? null,
    existing?.secondary ?? null,
    existing?.context ?? null,
    planType
  ) ?? existing;
}

function fallbackModelOptionsForBackend(backend: AssistantBackend): ProviderModelOption[] {
  if (backend === "copilot") {
    return [
      providerModelOption("auto", "Auto", "Let Copilot pick the best model"),
      providerModelOption("gpt-5.4", "GPT-5.4"),
      providerModelOption("gpt-5.3-codex", "GPT-5.3-Codex"),
      providerModelOption("gpt-5.2-codex", "GPT-5.2-Codex"),
      providerModelOption("gpt-5.2", "GPT-5.2"),
      providerModelOption("gpt-5.4-mini", "GPT-5.4 mini"),
      providerModelOption("gpt-5-mini", "GPT-5 mini"),
      providerModelOption("gpt-4.1", "GPT-4.1"),
      providerModelOption("claude-sonnet-4.6", "Claude Sonnet 4.6"),
      providerModelOption("claude-sonnet-4.5", "Claude Sonnet 4.5"),
      providerModelOption("claude-haiku-4.5", "Claude Haiku 4.5")
    ];
  }
  if (backend === "claudeCode") {
    return [
      providerModelOption("sonnet", "Claude Sonnet", "Balanced Claude Code model alias"),
      providerModelOption("opus", "Claude Opus", "Higher-capability Claude Code model alias"),
      providerModelOption("haiku", "Claude Haiku", "Fast Claude Code model alias")
    ];
  }
  if (backend === "antigravityCLI") {
    return antigravityModelOptions();
  }
  if (backend === "ollamaLocal") {
    return [
      providerModelOption("gemma4:e2b", "gemma4:e2b"),
      providerModelOption("llama3.2:latest", "llama3.2:latest"),
      providerModelOption("llama3.2:1b", "llama3.2:1b")
    ];
  }
  return [
    providerModelOption(readCodexDefaultModel(), readCodexDefaultModel()),
    providerModelOption("gpt-5.5", "GPT-5.5"),
    providerModelOption("gpt-5.4", "GPT-5.4"),
    providerModelOption("gpt-5.2", "GPT-5.2"),
    providerModelOption("gpt-5.3-codex", "GPT-5.3-Codex")
  ];
}

function uniqueProviderModels(models: ProviderModelOption[]) {
  const seen = new Set<string>();
  return models.filter((model) => {
    const normalized = model.id.trim().toLowerCase();
    if (!normalized || seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
}

function flattenCopilotConfigOptions(rawOptions: unknown): JsonObject[] {
  if (!Array.isArray(rawOptions)) return [];
  const flattened: JsonObject[] = [];
  for (const item of rawOptions) {
    const object = asObject(item);
    if (!object) continue;
    if (object.value !== undefined || object.modelId !== undefined) {
      flattened.push(object);
      continue;
    }
    flattened.push(...flattenCopilotConfigOptions(object.options));
  }
  return flattened;
}

function copilotModelFromRow(row: JsonObject, currentModelID?: string): ProviderModelOption | null {
  const id = pluginString(row.modelId, row.value)?.trim();
  if (!id) return null;
  const displayName = pluginString(row.name, row.displayName, id) ?? id;
  return {
    id,
    displayName,
    description: pluginString(row.description, displayName, id) ?? displayName,
    isDefault: Boolean(currentModelID && id.toLowerCase() === currentModelID.toLowerCase()),
    hidden: false,
    supportedReasoningEfforts: id.toLowerCase().startsWith("gpt-") ? ["low", "medium", "high", "xhigh"] : [],
    defaultReasoningEffort: id.toLowerCase().startsWith("gpt-") ? "high" : null,
    inputModalities: [],
    isInstalled: true
  };
}

let copilotModelCache: { expiresAt: number; value: ProviderModelOption[] } | null = null;
let ollamaModelCache: { expiresAt: number; value: ProviderModelOption[] } | null = null;
let ollamaCatalogCache: { expiresAt: number; value: OllamaCatalogModelOption[] } | null = null;
const ollamaModelsUsedThisSession = new Set<string>();

type OllamaModelDownloadProgress = {
  modelID: string;
  status: string;
  completed?: number;
  total?: number;
  percent?: number;
  done?: boolean;
  error?: string;
};

function normalizeOllamaModelName(rawModelID: unknown) {
  const modelID = pluginString(rawModelID)?.trim() ?? "";
  if (!modelID) throw new Error("Enter an Ollama model name.");
  if (/[\r\n]/.test(modelID)) throw new Error("Ollama model name must be one line.");
  return modelID;
}

function markOllamaModelUsed(modelID: unknown) {
  const normalized = pluginString(modelID)?.trim();
  if (normalized) ollamaModelsUsedThisSession.add(normalized);
}

async function resolveAvailableOllamaModelID(rawModelID: unknown) {
  const requested = pluginString(rawModelID)?.trim() || defaultLocalVoiceModel;
  const installed = await loadOllamaModelsFromTags();
  if (!installed.length) {
    throw new Error("No Ollama models are installed. Download a model before using Ollama.");
  }
  const exact = installed.find((model) => model.id.trim().toLowerCase() === requested.toLowerCase())?.id;
  if (exact) return exact;
  const defaultInstalled = installed.find((model) => model.id.trim().toLowerCase() === defaultLocalVoiceModel.toLowerCase())?.id;
  const fallback = defaultInstalled || installed.find((model) => model.id.trim())?.id;
  if (fallback) {
    bridgeDebugLog(`[ollama] model ${requested} is not installed; using ${fallback}`);
    return fallback;
  }
  throw new Error("No usable Ollama model is installed.");
}

async function parseOllamaError(response: Response, fallback: string) {
  let detail = "";
  try {
    const text = await response.text();
    if (text.trim().startsWith("{")) {
      const payload = JSON.parse(text) as JsonObject;
      detail = pluginString(payload.error, payload.message) ?? "";
    } else {
      detail = text.trim();
    }
  } catch {
    detail = "";
  }
  return detail ? `${fallback}: ${detail}` : fallback;
}

async function loadCopilotModelsFromACP(): Promise<ProviderModelOption[]> {
  const now = Date.now();
  if (copilotModelCache && copilotModelCache.expiresAt > now) return copilotModelCache.value;

  const models = await new Promise<ProviderModelOption[]>((resolve, reject) => {
    const child = spawn("copilot", ["--acp", "--stdio"], {
      cwd: openAssistRepoRoot(),
      env: { ...process.env, PATH: assistantPATH() },
      stdio: ["pipe", "pipe", "pipe"]
    });
    let buffer = "";
    let nextID = 0;
    let settled = false;
    const pending = new Map<number, {
      resolve: (value: JsonObject) => void;
      reject: (error: Error) => void;
      timer: ReturnType<typeof setTimeout>;
    }>();
    const finish = (callback: () => void) => {
      if (settled) return;
      settled = true;
      for (const item of pending.values()) {
        clearTimeout(item.timer);
      }
      pending.clear();
      child.kill("SIGTERM");
      callback();
    };
    const fail = (error: Error) => finish(() => reject(error));
    const send = (method: string, params: JsonObject) => {
      const id = nextID;
      nextID += 1;
      const message = JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n";
      return new Promise<JsonObject>((requestResolve, requestReject) => {
        const timer = setTimeout(() => {
          pending.delete(id);
          requestReject(new Error(`${method} timed out.`));
        }, 12_000);
        pending.set(id, { resolve: requestResolve, reject: requestReject, timer });
        child.stdin?.write(message, (error) => {
          if (!error) return;
          clearTimeout(timer);
          pending.delete(id);
          requestReject(error);
        });
      });
    };
    child.stdout?.setEncoding("utf8");
    child.stderr?.setEncoding("utf8");
    child.stdout?.on("data", (chunk) => {
      buffer += String(chunk);
      let newlineIndex = buffer.indexOf("\n");
      while (newlineIndex >= 0) {
        const line = buffer.slice(0, newlineIndex).trim();
        buffer = buffer.slice(newlineIndex + 1);
        newlineIndex = buffer.indexOf("\n");
        if (!line) continue;
        let message: JsonObject;
        try {
          message = JSON.parse(line) as JsonObject;
        } catch {
          continue;
        }
        const id = typeof message.id === "number" ? message.id : undefined;
        if (id === undefined || !pending.has(id)) continue;
        const request = pending.get(id);
        if (!request) continue;
        pending.delete(id);
        clearTimeout(request.timer);
        const error = asObject(message.error);
        if (error) {
          request.reject(new Error(pluginString(error.message) ?? "Copilot request failed."));
        } else {
          request.resolve((asObject(message.result) ?? {}) as JsonObject);
        }
      }
    });
    child.on("error", fail);
    child.on("close", (code) => {
      if (!settled && code !== 0) fail(new Error(`Copilot model list exited with code ${code}.`));
    });

    void (async () => {
      try {
        await send("initialize", {
          protocolVersion: 1,
          clientInfo: { name: "Open Assist", version: "1.0" },
          capabilities: {}
        });
        const session = await send("session/new", {
          cwd: openAssistRepoRoot(),
          mcpServers: []
        });
        const modelConfig = (Array.isArray(session.configOptions) ? session.configOptions : [])
          .map(asObject)
          .find((option) => option?.id === "model");
        const currentModelID = pluginString(asObject(session.models)?.currentModelId, modelConfig?.currentValue);
        const availableRows = flattenCopilotConfigOptions(asObject(session.models)?.availableModels);
        const configRows = flattenCopilotConfigOptions(modelConfig?.options);
        const rows = availableRows.length ? availableRows : configRows;
        const parsed = uniqueProviderModels(rows
          .map((row) => copilotModelFromRow(row, currentModelID))
          .filter(Boolean) as ProviderModelOption[]);
        finish(() => resolve(parsed.length ? parsed : fallbackModelOptionsForBackend("copilot")));
      } catch (error) {
        fail(error instanceof Error ? error : new Error("Could not load Copilot models."));
      }
    })();
  });

  copilotModelCache = { expiresAt: Date.now() + 60_000, value: models };
  return models;
}

async function loadOllamaModelsFromTags(): Promise<ProviderModelOption[]> {
  const now = Date.now();
  if (ollamaModelCache && ollamaModelCache.expiresAt > now) return ollamaModelCache.value;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 1500);
  try {
    const response = await fetch("http://127.0.0.1:11434/api/tags", { signal: controller.signal });
    if (!response.ok) throw new Error(`Ollama model list returned ${response.status}.`);
    const payload = await response.json() as JsonObject;
    const rows = Array.isArray(payload.models) ? payload.models : [];
    const models = uniqueProviderModels(rows
      .map((row) => {
        const object = asObject(row);
        const id = pluginString(object?.name, object?.model)?.trim();
        if (!id) return null;
        return providerModelOption(id, id, "Installed Ollama model");
      })
      .filter(Boolean) as ProviderModelOption[]);
    ollamaModelCache = { expiresAt: now + 30_000, value: models };
    return models;
  } finally {
    clearTimeout(timer);
  }
}

export async function listProviderModels(rawBackend: string): Promise<ProviderModelOption[]> {
  const backend = normalizeBackend(rawBackend);
  if (backend === "copilot") {
    try {
      return await loadCopilotModelsFromACP();
    } catch {
      return fallbackModelOptionsForBackend("copilot");
    }
  }
  if (backend === "antigravityCLI") {
    try {
      return await loadAntigravityModelsFromState();
    } catch {
      return fallbackModelOptionsForBackend("antigravityCLI");
    }
  }
  if (backend === "ollamaLocal") {
    try {
      return await loadOllamaModelsFromTags();
    } catch {
      return fallbackModelOptionsForBackend("ollamaLocal");
    }
  }
  return fallbackModelOptionsForBackend(backend);
}

function percentFromOllamaProgress(completed?: number, total?: number) {
  if (!completed || !total || total <= 0) return undefined;
  return Math.max(0, Math.min(100, Math.round((completed / total) * 100)));
}

async function readOllamaPullStream(
  response: Response,
  modelID: string,
  onProgress?: (progress: OllamaModelDownloadProgress) => void
) {
  if (!response.body) return;
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let lastProgress: OllamaModelDownloadProgress = { modelID, status: "Downloading" };
  const emit = (progress: OllamaModelDownloadProgress) => {
    lastProgress = { ...lastProgress, ...progress, modelID };
    onProgress?.(lastProgress);
  };
  emit({ modelID, status: "Starting download", percent: 0 });
  while (true) {
    const { done, value } = await reader.read();
    buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
    const lines = buffer.split(/\r?\n/);
    buffer = done ? "" : lines.pop() ?? "";
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      let payload: JsonObject;
      try {
        payload = JSON.parse(trimmed) as JsonObject;
      } catch {
        continue;
      }
      const error = pluginString(payload.error);
      if (error) {
        emit({ modelID, status: "Download failed", error });
        throw new Error(error);
      }
      const status = pluginString(payload.status) ?? "Downloading";
      const completed = typeof payload.completed === "number" ? payload.completed : undefined;
      const total = typeof payload.total === "number" ? payload.total : undefined;
      emit({
        modelID,
        status,
        completed,
        total,
        percent: percentFromOllamaProgress(completed, total)
      });
    }
    if (done) break;
  }
}

async function pullOllamaModel(
  rawModelID: string,
  onProgress?: (progress: OllamaModelDownloadProgress) => void
): Promise<{ ok: boolean; modelID: string; models: ProviderModelOption[] }> {
  const modelID = normalizeOllamaModelName(rawModelID);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 90 * 60_000);
  try {
    const response = await fetch("http://127.0.0.1:11434/api/pull", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: controller.signal,
      body: JSON.stringify({ name: modelID, stream: true })
    });
    if (!response.ok) {
      throw new Error(await parseOllamaError(response, `Could not download ${modelID}`));
    }
    await readOllamaPullStream(response, modelID, onProgress);
    ollamaModelCache = null;
    ollamaCatalogCache = null;
    onProgress?.({ modelID, status: "Downloaded", percent: 100, done: true });
    return {
      ok: true,
      modelID,
      models: await loadOllamaModelsFromTags().catch(() => fallbackModelOptionsForBackend("ollamaLocal"))
    };
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      onProgress?.({ modelID, status: "Download timed out", error: "Download took too long." });
      throw new Error(`Downloading ${modelID} took too long. Ollama may still be pulling it in the background.`);
    }
    if (error instanceof Error) {
      let message = error.message;
      if (isOllamaVersionUpgradeError(message)) {
        try {
          const runtimeStatus = await getOllamaRuntimeStatus();
          message = formatOllamaUpgradeHint(message, runtimeStatus.latestVersion);
        } catch {
          message = formatOllamaUpgradeHint(message);
        }
      }
      onProgress?.({ modelID, status: "Download failed", error: message });
      throw new Error(message);
    }
    throw new Error(`Could not download ${modelID}.`);
  } finally {
    clearTimeout(timer);
  }
}

async function buildOllamaCatalogModels(includeWebsite = false): Promise<OllamaCatalogModelOption[]> {
  const memoryBytes = physicalMemoryBytes();
  let catalog = curatedOllamaCatalog(memoryBytes);
  if (includeWebsite && ollamaCatalogCache && ollamaCatalogCache.expiresAt > Date.now()) {
    catalog = ollamaCatalogCache.value;
  } else if (includeWebsite) {
    const websiteModels = await fetchOllamaWebsiteModelOptions(12);
    catalog = mergeCatalogWithWebsiteModels(curatedOllamaCatalog(memoryBytes), websiteModels);
    ollamaCatalogCache = { expiresAt: Date.now() + 5 * 60_000, value: catalog };
  }
  const installed = await loadOllamaModelsFromTags().catch(() => [] as ProviderModelOption[]);
  const installedIDs = installed.map((model) => model.id);
  return sortOllamaCatalog(mergeCatalogWithInstalled(catalog, installedIDs));
}

async function listOllamaCatalogModels(): Promise<OllamaCatalogModelOption[]> {
  return buildOllamaCatalogModels(Boolean(ollamaCatalogCache && ollamaCatalogCache.expiresAt > Date.now()));
}

async function refreshOllamaWebsiteCatalog(): Promise<{
  ok: boolean;
  models: OllamaCatalogModelOption[];
  statusMessage: string;
}> {
  const curated = curatedOllamaCatalog(physicalMemoryBytes());
  const curatedCount = curated.length;
  try {
    const websiteModels = await fetchOllamaWebsiteModelOptions(12);
    const merged = mergeCatalogWithWebsiteModels(curated, websiteModels);
    ollamaCatalogCache = { expiresAt: Date.now() + 5 * 60_000, value: merged };
    const installed = await loadOllamaModelsFromTags().catch(() => [] as ProviderModelOption[]);
    const models = sortOllamaCatalog(mergeCatalogWithInstalled(merged, installed.map((model) => model.id)));
    return {
      ok: true,
      models,
      statusMessage: websiteCatalogStatusMessage(merged, curatedCount)
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const installed = await loadOllamaModelsFromTags().catch(() => [] as ProviderModelOption[]);
    const models = sortOllamaCatalog(mergeCatalogWithInstalled(curated, installed.map((model) => model.id)));
    return {
      ok: false,
      models,
      statusMessage: websiteCatalogStatusMessage([], curatedCount, message)
    };
  }
}

async function deleteOllamaModel(rawModelID: string): Promise<{ ok: boolean; modelID: string; models: ProviderModelOption[] }> {
  const modelID = normalizeOllamaModelName(rawModelID);
  const response = await fetch("http://127.0.0.1:11434/api/delete", {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: modelID })
  });
  if (!response.ok) {
    throw new Error(await parseOllamaError(response, `Could not delete ${modelID}`));
  }
  ollamaModelCache = null;
  ollamaCatalogCache = null;
  return {
    ok: true,
    modelID,
    models: await loadOllamaModelsFromTags().catch(() => fallbackModelOptionsForBackend("ollamaLocal"))
  };
}

